WITH base_tasks AS
  (SELECT COALESCE(NULLIF(TRIM(PARENT_PART_NUMBER::VARCHAR), ''), '<Missing>') AS PARENT_PART_NUMBER,
          IMPUTED_DWELL_IN_PROGRESS_TO_CLOSED_SECONDS AS DURATION_SECONDS
   FROM EDLDB_DEV.PET_HEALTH_ANALYTICS_SANDBOX.MY_RXP_VALID_DUR_TASKS
   WHERE USER_ID IS NOT NULL
     AND TASK_ID IS NOT NULL
     AND PROCESS_START_TIME IS NOT NULL
     AND IMPUTED_DWELL_IN_PROGRESS_TO_CLOSED_SECONDS > 0
     AND MC3_COH_PETTYPE_SEQN IS NOT NULL
     AND MC3_COH_PETTYPE_BATCH_LEN IS NOT NULL
     AND MC3_COH_PETTYPE_SEQN >= 1
     AND MC3_COH_PETTYPE_BATCH_LEN >= 1
     AND MC3_COH_PETTYPE_SEQN <= MC3_COH_PETTYPE_BATCH_LEN),
     duration_cutoff AS
  (SELECT APPROX_PERCENTILE(DURATION_SECONDS, 0.95) AS P95_SECONDS
   FROM base_tasks),
     filtered_tasks AS
  (SELECT base_tasks.*
   FROM base_tasks
   CROSS JOIN duration_cutoff
   WHERE base_tasks.DURATION_SECONDS < duration_cutoff.P95_SECONDS)
SELECT COUNT(*) AS TASKS,
       COUNT(DISTINCT PARENT_PART_NUMBER) AS PARENT_PART_NUMBER_LEVELS_INCLUDING_MISSING,
       COUNT(DISTINCT IFF(PARENT_PART_NUMBER = '<Missing>', NULL, PARENT_PART_NUMBER)) AS NONMISSING_PARENT_PART_NUMBERS,
       COUNT_IF(PARENT_PART_NUMBER = '<Missing>') AS TASKS_WITH_MISSING_PARENT_PART_NUMBER
FROM filtered_tasks
